package dao;
import java.sql.*;
import java.time.LocalDate;
import java.util.*;
import negocio.*;
public class JugadorCategoriaDAOMySQL implements JugadorCategoriaDAO {
 public void guardar(Connection c,JugadorCategoria x){String q="INSERT INTO jugador_categorias(perfil_jugador_id,categoria_deportiva_id,fecha_desde,fecha_hasta,estado,origen,motivo,observaciones,usuario_responsable_id) VALUES(?,?,?,?,?,?,?,?,?)";try(PreparedStatement s=c.prepareStatement(q,Statement.RETURN_GENERATED_KEYS)){s.setLong(1,x.getPerfilJugadorId());s.setLong(2,x.getCategoriaDeportivaId());s.setDate(3,java.sql.Date.valueOf(x.getFechaDesde()));if(x.getFechaHasta()==null)s.setNull(4,Types.DATE);else s.setDate(4,java.sql.Date.valueOf(x.getFechaHasta()));s.setString(5,x.getEstado().name());s.setString(6,x.getOrigen().name());s.setString(7,x.getMotivo());s.setString(8,x.getObservaciones());if(x.getUsuarioResponsableId()==null)s.setNull(9,Types.BIGINT);else s.setLong(9,x.getUsuarioResponsableId());s.executeUpdate();try(ResultSet r=s.getGeneratedKeys()){if(r.next())x.setId(r.getLong(1));}}catch(SQLException e){throw e.getErrorCode()==1062?new IllegalArgumentException("El jugador ya tiene una categoría vigente.",e):new RuntimeException("No se pudo asignar la categoría.",e);}}
 public JugadorCategoria buscarVigente(Connection c,long id){List<JugadorCategoria>x=list(c,id," AND estado='VIGENTE' LIMIT 1");return x.isEmpty()?null:x.getFirst();}
 public List<JugadorCategoria> listarHistorial(Connection c,long id){return list(c,id," ORDER BY fecha_desde DESC,id DESC");}
 private List<JugadorCategoria> list(Connection c,long id,String tail){String q="SELECT id,perfil_jugador_id,categoria_deportiva_id,fecha_desde,fecha_hasta,estado,origen,motivo,observaciones,usuario_responsable_id,fecha_registro FROM jugador_categorias WHERE perfil_jugador_id=?"+tail;try(PreparedStatement s=c.prepareStatement(q)){s.setLong(1,id);try(ResultSet r=s.executeQuery()){List<JugadorCategoria>o=new ArrayList<>();while(r.next()){JugadorCategoria x=new JugadorCategoria();x.setId(r.getLong(1));x.setPerfilJugadorId(r.getLong(2));x.setCategoriaDeportivaId(r.getLong(3));x.setFechaDesde(r.getDate(4).toLocalDate());java.sql.Date h=r.getDate(5);if(h!=null)x.setFechaHasta(h.toLocalDate());x.setEstado(EstadoJugadorCategoria.valueOf(r.getString(6)));x.setOrigen(OrigenJugadorCategoria.valueOf(r.getString(7)));x.setMotivo(r.getString(8));x.setObservaciones(r.getString(9));long u=r.getLong(10);x.setUsuarioResponsableId(r.wasNull()?null:u);o.add(x);}return o;}}catch(SQLException e){throw new RuntimeException("No se pudo consultar el historial de categorías.",e);}}
 public void finalizarVigente(Connection c,long id,LocalDate hasta){try(PreparedStatement s=c.prepareStatement("UPDATE jugador_categorias SET estado='FINALIZADA',fecha_hasta=? WHERE perfil_jugador_id=? AND estado='VIGENTE'")){s.setDate(1,java.sql.Date.valueOf(hasta));s.setLong(2,id);s.executeUpdate();}catch(SQLException e){throw new RuntimeException("No se pudo cerrar la categoría vigente.",e);}}
 public void cerrarVigente(Connection c,long perfilId,LocalDate hasta,EstadoJugadorCategoria estado,String motivo,String observaciones,Long usuarioId){String q="UPDATE jugador_categorias SET estado=?,fecha_hasta=?,motivo=?,observaciones=?,usuario_responsable_id=? WHERE perfil_jugador_id=? AND estado='VIGENTE'";try(PreparedStatement s=c.prepareStatement(q)){s.setString(1,estado.name());s.setDate(2,java.sql.Date.valueOf(hasta));s.setString(3,motivo);s.setString(4,observaciones);if(usuarioId==null)s.setNull(5,Types.BIGINT);else s.setLong(5,usuarioId);s.setLong(6,perfilId);if(s.executeUpdate()==0)throw new IllegalArgumentException("El jugador no tiene una categoría vigente.");}catch(SQLException e){throw new RuntimeException("No se pudo cerrar la categoría vigente.",e);}}
}
